rd{min-height:155px;border:1px solid var(--line);border-radius:12px;background:#fff;overflow:hidden;display:grid;grid-template-columns:178px 1fr}.article-card>a:first-child,.article-fallback{height:100%;min-height:155px;background:var(--soft);display:block}.article-card img{width:100%;height:100%;object-fit:cover}.article-card-body{padding:12px;display:flex;flex-direction:column}.article-card-body time{color:var(--muted);font-size:12px}.article-card-body h3{margin:5px 0;color:var(--primary-dark);font-size:16px}.article-card-body p{color:var(--muted);font-size:13px;line-height:1.5}.more{margin-top:auto;color:var(--primary);font-weight:bold;font-size:13px}@media(max-width:850px){.editorial-grid{grid-template-columns:1fr}.feature-card{order:1}.recent-panel{order:2}.article-grid{grid-template-columns:1fr}}@media(max-width:560px){.feature-card{grid-template-columns:1fr}.feature-media{min-height:210px}.article-card{grid-template-columns:120px 1fr}.article-card>a:first-child,.article-fallback{min-height:145px}}
</style>
<div class="container news-page"><div class="breadcrumb"><a href="<?php echo $base_url; ?>"><i class="fas fa-home"></i> Trang chủ</a><i class="fas fa-chevron-right"></i><span>Tin tức</span></div><section class="news-intro"><div><small>CẨM NANG CÔNG NGHỆ</small><h1>Kiến thức và kinh nghiệm chọn thiết bị</h1><p>Gợi ý dễ áp dụng về cấu hình, kết nối, bảo hành và cách sử dụng thiết bị.</p></div><i class="fas fa-newspaper"></i></section><?php if($featured):?><section class="editorial-grid"><article class="feature-card"><div class="feature-media"><?php if($featured['thumbnail']):?><img src="<?php echo htmlspecialchars(media_url($featured['thumbnail'],$base_url)); ?>" alt="<?php echo htmlspecialchars($featured['title']); ?>"><?php else:?><div class="article-fallback"><i class="fas fa-newspaper"></i></div><?php endif;?></div><div class="feature-copy"><time><?php echo date('d/m/Y',strtotime($featured['created_at'])); ?></time><h2><?php echo htmlspecialchars($featured['title']); ?></h2><p><?php echo htmlspecialchars(mb_substr(strip_tags($featured['content']),0,230)); ?>...</p><a class="read-more" href="<?php echo $base_url.'tin-tuc/'.createSlug($featured['title']).'-'.$featured['id']; ?>">Đọc bài viết <i class="fas fa-arrow-right"></i></a></div></article><aside class="recent-panel"><h2 class="recent-title">Bài mới cập nhật</h2><div class="recent-list"><?php foreach(array_slice($items,1,4) as $n):?><a class="mini-news" href="<?php echo $base_url.'tin-tuc/'.createSlug($n['title']).'-'.$n['id']; ?>"><?php if($n['thumbnail']):?><img src="<?php echo htmlspecialchars(media_url($n['thumbnail'],$base_url)); ?>" alt="<?php echo htmlspecialchars($n['title']); ?>"><?php else:?><div class="mini-fallback"><i class="fas fa-file-lines"></i></div><?php endif;?><div><time><?php echo date('d/m/Y',strtotime($n['created_at'])); ?></time><h3><?php echo htmlspecialchars($n['title']); ?></h3></div></a><?php endforeach;?></div></aside></section><?php endif;?><div class="news-section-head"><h2>Tất cả bài viết</h2><span>Kiến thức hữu ích trước khi chọn và sử dụng thiết bị</span></div><section class="article-grid"><?php foreach(array_slice($items,5) as $n):?><article class="article-card"><?php if($n['thumbnail']):?><img src="<?php echo htmlspecialchars(media_url($n['thumbnail'],$base_url)); ?>" alt="<?php echo htmlspecialchars($n['title']); ?>"><?php else:?><div class="article-fallback"><i class="fas fa-file-lines"></i></div><?php endif;?><div class="article-card-body"><time><?php echo date('d/m/Y',strtotime($n['created_at'])); ?></time><a href="<?php echo $base_url.'tin-tuc/'.createSlug($n['title']).'-'.$n['id']; ?>"><h3><?php echo htmlspecialchars($n['title']); ?></h3></a><p><?php echo htmlspecialchars(mb_substr(strip_tags($n['content']),0,130)); ?>...</p><a class="more" href="<?php echo $base_url.'tin-tuc/'.createSlug($n['title']).'-'.$n['id']; ?>">Xem chi tiết <i class="fas fa-arrow-right"></i></a></div></article><?php endforeach;?></section></div><?php require_once 'footer.php'; ?>
